function DropdownlistFilterWidget() {
this.getAssociatedTypes = function () { return ["DropdownlistFilterWidget"] }; this.onShow = function () { }; this.showClearFilterButton = function () { return !0 }; this.onRender = function (container, lang, typeName, values, cb, data) { this.cb = cb; this.container = container; this.lang = lang; this.value = values.length > 0 ? values[0] : { filterType: 1, filterValue: "" }; this.renderWidget(); this.fillDropDownList($.parseJSON(data)); this.registerEvents() }; this.renderWidget = function () {
    var html = '<p><i>This is custom filter widget demo.</i></p>\
                    <p>Select customer to filter:</p>\
                    <select style="width:250px;" class="grid-filter-type list form-control">\
                    </select>'; this.container.append(html)
}; this.fillDropDownList = function (items) { var List = this.container.find(".list"); for (var i = 0; i < items.length; i++) { List.append('<option ' + (items[i] == this.value.filterValue ? 'selected="selected"' : '') + ' value="' + items[i] + '">' + items[i] + '</option>') } }; this.registerEvents = function () {
    var List = this.container.find(".list"); var $context = this; List.change(function () {
        var index = List.parents('th').index(); var table = List.parents('table'); $("td:nth-child(" + (index + 1) + ")").each(function () { $(this).find('select').val(List.val()) }); var openedPopup = table.find(".dropdown-menu.opened"); openedPopup.hide(); openedPopup.removeClass("opened"); if (this.openedMenuBtn != null)
            this.openedMenuBtn.removeClass("clicked")
    })
}
}